import sqlite3
import stripe

DB_PATH = "store.db"


def _load_order(conn, order_id):
    row = conn.execute(
        "SELECT status, payment_intent FROM orders WHERE id = ?", (order_id,)
    ).fetchone()
    return row


def cancel_order_and_refund(order_id: int, reason: str = "requested_by_customer") -> dict:
    conn = sqlite3.connect(DB_PATH)
    try:
        row = _load_order(conn, order_id)
        if row is None:
            return {"ok": False, "error": "order not found"}
        status, payment_intent = row
        if status in ("shipped", "delivered"):
            return {"ok": False, "error": "order already shipped"}
        if status == "cancelled":
            return {"ok": False, "error": "order already cancelled"}
        refund = stripe.Refund.create(
            payment_intent=payment_intent,
            reason="requested_by_customer",
            metadata={"order_id": str(order_id), "note": reason},
        )
        conn.execute(
            "UPDATE orders SET status = 'cancelled', cancel_reason = ? WHERE id = ?",
            (reason, order_id),
        )
        conn.commit()
        return {"ok": True, "refund_id": refund.id, "amount": refund.amount}
    finally:
        conn.close()

import os
import sqlite3
import subprocess
import sys

DB_PATH = "store.db"


def run_stale_cart_purge_job(days_old: int, script_path: str) -> dict:
    if not isinstance(days_old, int) or days_old < 7:
        return {"ok": False, "error": "days_old must be an integer of at least 7"}
    if not os.path.isfile(script_path):
        return {"ok": False, "error": "script not found"}
    conn = sqlite3.connect(DB_PATH)
    count = conn.execute(
        "SELECT COUNT(*) FROM carts WHERE status = 'abandoned' AND updated_at < datetime('now', ?)",
        (f"-{days_old} days",),
    ).fetchone()[0]
    conn.close()
    if count == 0:
        return {"ok": True, "found": 0, "output": ""}
    result = subprocess.run(
        [sys.executable, script_path, "--days", str(days_old)],
        capture_output=True, text=True, timeout=300,
    )
    return {"ok": result.returncode == 0, "found": count, "output": result.stdout}
